describe('API Response Caching', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should cache API response and return instant data on repeat visits', () => {
    // First request - should hit API and cache response
    cy.intercept('GET', '/api/data').as('firstRequest');
    cy.wait('@firstRequest');
    cy.get('[data-testid="api-response-content"]').should('be.visible');
    cy.get('[data-testid="api-response-content"]').should('contain', 'Data loaded');

    // Verify cache is set
    cy.window().then((win) => {
      expect(win.localStorage.getItem('api-data-cache')).to.not.be.null;
    });

    // Second request - should hit cache instead of API
    cy.intercept('GET', '/api/data').as('secondRequest');
    cy.wait('@secondRequest');
    cy.get('[data-testid="api-response-content"]').should('be.visible');
    cy.get('[data-testid="api-response-content"]').should('contain', 'Data loaded');

    // Verify cache is still set
    cy.window().then((win) => {
      expect(win.localStorage.getItem('api-data-cache')).to.not.be.null;
    });

    // Clear cache
    cy.window().then((win) => {
      win.localStorage.removeItem('api-data-cache');
    });

    // Third request - should hit API again
    cy.intercept('GET', '/api/data').as('thirdRequest');
    cy.wait('@thirdRequest');
    cy.get('[data-testid="api-response-content"]').should('be.visible');
    cy.get('[data-testid="api-response-content"]').should('contain', 'Data loaded');

    // Verify cache is cleared
    cy.window().then((win) => {
      expect(win.localStorage.getItem('api-data-cache')).to.be.null;
    });
  });

  it('should handle cache expiration and refresh data', () => {
    // First request - cache data
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: 'Initial data',
        expires: '2023-04-01T00:00:00Z'
      }
    }).as('firstRequest');
    cy.wait('@firstRequest');
    cy.get('[data-testid="api-response-content"]').should('be.visible');
    cy.get('[data-testid="api-response-content"]').should('contain', 'Initial data');

    // Wait for cache expiration
    cy.window().then((win) => {
      const cacheExpiry = new Date(win.localStorage.getItem('api-data-cache')).getTime();
      const currentTime = new Date().getTime();
      expect(currentTime - cacheExpiry).to.be.greaterThan(60000); // 1 minute
    });

    // Second request - should hit API and refresh data
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: 'Updated data',
        expires: '2023-04-02T00:00:00Z'
      }
    }).as('refreshRequest');
    cy.wait('@refreshRequest');
    cy.get('[data-testid="api-response-content"]').should('be.visible');
    cy.get('[data-testid="api-response-content"]').should('contain', 'Updated data');

    // Verify cache is still set but expired
    cy.window().then((win) => {
      expect(win.localStorage.getItem('api-data-cache')).to.not.be.null;
      const cacheExpiry = new Date(win.localStorage.getItem('api-data-cache')).getTime();
      expect(currentTime - cacheExpiry).to.be.greaterThan(60000);
    });
  });
});
